// Material de Construcao Coragem - interacoes do site
(function () {
  "use strict";

    var WHATSAPP_NUMBER = "5521981691223";

      function waLink(message) {
          return "https://wa.me/" + WHATSAPP_NUMBER + "?text=" + encodeURIComponent(message);
            }

              // ---- Mobile nav ----
                function initMobileNav() {
                    var toggle = document.querySelector("[data-nav-toggle]");
                        var close = document.querySelector("[data-nav-close]");
                            var drawer = document.querySelector("[data-mobile-nav]");
                                if (!toggle || !drawer) return;

                                    function open() {
                                          drawer.classList.add("open");
                                                document.body.style.overflow = "hidden";
                                                    }
                                                        function shut() {
                                                              drawer.classList.remove("open");
                                                                    document.body.style.overflow = "";
                                                                        }
                                                                            toggle.addEventListener("click", open);
                                                                                if (close) close.addEventListener("click", shut);
                                                                                    drawer.querySelectorAll("a").forEach(function (a) {
                                                                                          a.addEventListener("click", shut);
                                                                                              });
                                                                                                }

                                                                                                  // ---- Header shadow on scroll ----
                                                                                                    function initHeaderScroll() {
                                                                                                        var header = document.querySelector("[data-site-header]");
                                                                                                            if (!header) return;
                                                                                                                function onScroll() {
                                                                                                                      if (window.scrollY > 8) header.style.boxShadow = "0 4px 16px rgba(11,43,92,.08)";
                                                                                                                            else header.style.boxShadow = "none";
                                                                                                                                }
                                                                                                                                    window.addEventListener("scroll", onScroll, { passive: true });
                                                                                                                                        onScroll();
                                                                                                                                          }
                                                                                                                                          
                                                                                                                                            // ---- Quote form -> WhatsApp ----
                                                                                                                                              function initQuoteForm() {
                                                                                                                                                  var form = document.querySelector("[data-quote-form]");
                                                                                                                                                      if (!form) return;
                                                                                                                                                      
                                                                                                                                                          form.addEventListener("submit", function (e) {
                                                                                                                                                                e.preventDefault();
                                                                                                                                                                
                                                                                                                                                                      var nome = (form.querySelector("#f-nome") || {}).value || "";
                                                                                                                                                                            var bairro = (form.querySelector("#f-bairro") || {}).value || "";
                                                                                                                                                                                  var entrega = form.querySelector('input[name="entrega"]:checked');
                                                                                                                                                                                        var entregaVal = entrega ? entrega.value : "";
                                                                                                                                                                                              var detalhes = (form.querySelector("#f-detalhes") || {}).value || "";
                                                                                                                                                                                              
                                                                                                                                                                                                    var categorias = [];
                                                                                                                                                                                                          form.querySelectorAll('input[name="categoria"]:checked').forEach(function (el) {
                                                                                                                                                                                                                  categorias.push(el.value);
                                                                                                                                                                                                                        });
                                                                                                                                                                                                                        
                                                                                                                                                                                                                              var linhas = [];
                                                                                                                                                                                                                                    linhas.push("Ola! Vim pelo site e gostaria de um orcamento.");
                                                                                                                                                                                                                                          if (nome.trim()) linhas.push("Nome: " + nome.trim());
                                                                                                                                                                                                                                                if (bairro.trim()) linhas.push("Bairro: " + bairro.trim());
                                                                                                                                                                                                                                                      if (categorias.length) linhas.push("Preciso de: " + categorias.join(", "));
                                                                                                                                                                                                                                                            if (detalhes.trim()) linhas.push("Detalhes: " + detalhes.trim());
                                                                                                                                                                                                                                                                  if (entregaVal) linhas.push("Prefiro: " + entregaVal);
                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                        var msg = linhas.join("\n");
                                                                                                                                                                                                                                                                              window.open(waLink(msg), "_blank", "noopener");
                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                      // ---- Generic WhatsApp buttons with data-wa-message ----
                                                                                                                                                                                                                                                                                        function initWaButtons() {
                                                                                                                                                                                                                                                                                            document.querySelectorAll("[data-wa-message]").forEach(function (btn) {
                                                                                                                                                                                                                                                                                                  var msg = btn.getAttribute("data-wa-message");
                                                                                                                                                                                                                                                                                                        btn.setAttribute("href", waLink(msg));
                                                                                                                                                                                                                                                                                                              btn.setAttribute("target", "_blank");
                                                                                                                                                                                                                                                                                                                    btn.setAttribute("rel", "noopener");
                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                            // ---- Active nav link ----
                                                                                                                                                                                                                                                                                                                              function initActiveLink() {
                                                                                                                                                                                                                                                                                                                                  var path = window.location.pathname.split("/").pop() || "index.html";
                                                                                                                                                                                                                                                                                                                                      document.querySelectorAll("[data-nav-link]").forEach(function (a) {
                                                                                                                                                                                                                                                                                                                                            var href = a.getAttribute("href");
                                                                                                                                                                                                                                                                                                                                                  if (href === path || (path === "" && href === "index.html")) {
                                                                                                                                                                                                                                                                                                                                                          a.classList.add("active");
                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                        // ---- Smooth scroll (Lenis) ----
                                                                                                                                                                                                                                                                                                                                                                          function initSmoothScroll() {
                                                                                                                                                                                                                                                                                                                                                                              if (typeof window.Lenis !== "function") return null;
                                                                                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                                                                                        var lenis = new window.Lenis({
                                                                                                                                                                                                                                                                                                                                                                                                duration: 1.05,
                                                                                                                                                                                                                                                                                                                                                                                                        smoothWheel: true,
                                                                                                                                                                                                                                                                                                                                                                                                                autoRaf: false,
                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                            function raf(time) {
                                                                                                                                                                                                                                                                                                                                                                                                                                    lenis.raf(time);
                                                                                                                                                                                                                                                                                                                                                                                                                                            requestAnimationFrame(raf);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        requestAnimationFrame(raf);
                                                                                                                                                                                                                                                                                                                                                                                                                                                              return lenis;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ---- Scroll-reveal animations (GSAP + ScrollTrigger) ----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function initScrollReveal(lenis) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!window.gsap || !window.ScrollTrigger) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var gsap = window.gsap;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              gsap.registerPlugin(window.ScrollTrigger);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (lenis) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lenis.on("scroll", window.ScrollTrigger.update);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              gsap.ticker.add(function (time) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      lenis.raf(time * 1000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  gsap.ticker.lagSmoothing(0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var prefersReducedMotion = window.matchMedia
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? window.matchMedia("(prefers-reduced-motion: reduce)").matches
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (prefersReducedMotion) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var groups = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ".grid",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ".two-col",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ".chip-row",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ".check-grid",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ".footer-grid",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    groups.forEach(function (sel) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.querySelectorAll(sel).forEach(function (container) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var items = container.children;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!items.length) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  gsap.from(items, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            opacity: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      y: 26,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                duration: 0.6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ease: "power2.out",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stagger: 0.08,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              scrollTrigger: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          trigger: container,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      start: "top 88%",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var singles = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ".review-banner",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ".cta-band",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ".hero-panel",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ".map-wrap",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ".page-hero > *",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            singles.forEach(function (sel) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.querySelectorAll(sel).forEach(function (el) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          gsap.from(el, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    opacity: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              y: 22,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        duration: 0.65,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ease: "power2.out",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            scrollTrigger: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        trigger: el,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    start: "top 90%",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.querySelectorAll(".faq-item").forEach(function (el, i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          gsap.from(el, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  opacity: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          y: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  duration: 0.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ease: "power2.out",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  delay: Math.min(i * 0.04, 0.3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          scrollTrigger: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    trigger: el,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              start: "top 92%",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ---- Hero rating stars: small pop-in with Motion ----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function initHeroPop() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var animate = window.Motion && window.Motion.animate;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!animate) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var stars = document.querySelectorAll(".hero-panel .stars svg, .hero-panel svg");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!stars.length) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                stars.forEach(function (star, i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        animate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  star,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            { opacity: [0, 1], scale: [0.6, 1] },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      { duration: 0.4, delay: i * 0.06, easing: [0.34, 1.56, 0.64, 1] }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.addEventListener("DOMContentLoaded", function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    initMobileNav();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        initHeaderScroll();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            initQuoteForm();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                initWaButtons();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    initActiveLink();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var lenis = initSmoothScroll();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            initScrollReveal(lenis);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                initHeroPop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
